-- Iowa. The state had six stops, four of them duplicated in this file.
--
-- Iowa is half the reason Chicago to Denver has been the emptiest long route
-- in the index. Nebraska is the other half.
--
-- Four dropped. Two are the apostrophe again: the popcorn ball and the
-- strawberry are held as world-s-largest rather than worlds-largest, so only
-- the second slug convention finds them. Fifth and sixth time that has hidden
-- a duplicate, and the reason the check tries both spellings.
--
-- Rusty the Giant Sloth is dropped as a feature rather than a stop — the
-- University of Iowa museum's star specimen, at zero metres from the museum.
--
-- Kept despite flagging: Riverside has three Star Trek entries within fifty
-- metres, being the birthplace marker, the history centre and the festival
-- ground. A town of nine hundred people built three separate things out of
-- one line of dialogue.
--
-- 161 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Villisca Axe Murder House', 'villisca-axe-murder-house', 'weird-history', 40.93072, -94.9733, 'Villisca', 'IA', 'The modest Moore family house is the scene of Iowa''s infamous unsolved 1912 axe murders, in which eight people were killed overnight. The restored property now offers scheduled daytime tours and overnight stays, making it one of the state''s strongest legitimate dark-history and paranormal destinations.', 'limited', 'https://www.villiscaiowa.com/', null, 'America/Chicago', now()),
  ('Edinburgh Manor', 'edinburgh-manor', 'haunted', 42.1591, -91.1768, 'Scotch Grove', 'IA', 'This former Jones County poor farm and later care facility is now operated specifically for tours and paranormal investigations. Its institutional history, isolated setting and preserved interior have made it one of Iowa''s best-known ghost-hunting locations.', 'limited', 'https://edinburghmanor.wixsite.com/edinburgh', null, 'America/Chicago', now()),
  ('Farrar Schoolhouse', 'farrar-schoolhouse', 'haunted', 41.7849, -93.8436, 'Farrar', 'IA', 'The 1920s Farrar school building is privately operated as a paranormal investigation destination, with scheduled tours and overnight access. OddWay visitors should book through the operator rather than treating the building as abandoned.', 'limited', 'https://farrarschoolhouse.com/', null, 'America/Chicago', now()),
  ('Squirrel Cage Jail', 'squirrel-cage-jail', 'weird-history', 41.2615, -95.8591, 'Council Bluffs', 'IA', 'This rare nineteenth-century rotary jail once moved pie-slice-shaped cells around a central mechanism like a human-sized carousel. The preserved mechanism and confined architecture make it one of Iowa''s strangest historic buildings.', 'limited', 'https://www.thehistoricalsociety.org/squirrel-cage-jail.html', null, 'America/Chicago', now()),
  ('Black Angel — Oakland Cemetery', 'black-angel-oakland-cemetery', 'folklore', 41.67, -91.52, 'Iowa City', 'IA', 'A large darkened bronze angel marks the Feldevert family grave in Oakland Cemetery and has accumulated decades of local legends involving curses, death and supernatural consequences for touching or kissing it. Treat the stories as folklore and visit respectfully during cemetery hours.', 'limited', 'https://www.icgov.org/government/departments-and-divisions/parks-and-recreation/cemeteries', null, 'America/Chicago', now()),
  ('Mars Hill Church', 'mars-hill-church', 'folklore', 40.89946, -92.35751, 'Bloomfield', 'IA', 'This isolated historic church is associated with long-running southeastern Iowa ghost stories involving lights, apparitions and unsettling nighttime encounters. The haunting claims are folklore; travelers should remain on lawful public access and respect the church and surrounding property.', 'roadside', 'https://www.hauntedplaces.org/item/mars-hill-church/', null, 'America/Chicago', now()),
  ('Terror Bridge', 'terror-bridge', 'folklore', 42.50458, -94.34449, 'Fort Dodge', 'IA', 'A rural bridge north of Fort Dodge is tied to local stories of a woman, children and unexplained sounds around the crossing. The legend is unverified folklore, and OddWay should treat the bridge only as a public-road stop with no entry onto adjacent private land.', 'roadside', 'https://www.hauntedplaces.org/item/bannwell-bridge-terror-bridge/', null, 'America/Chicago', now()),
  ('Mason House Inn', 'mason-house-inn', 'haunted', 40.7218, -91.8544, 'Bentonsport', 'IA', 'Built in the nineteenth century along the Des Moines River, the Mason House Inn has hosted travelers for generations and openly embraces stories of reported apparitions and unexplained activity. It remains an operating inn, so access is through lodging or scheduled events.', 'limited', 'https://www.masonhouseinn.com/', null, 'America/Chicago', now()),
  ('Franklin Hotel', 'franklin-hotel', 'haunted', 42.68361, -91.53389, 'Strawberry Point', 'IA', 'The historic Franklin Hotel is one of Strawberry Point''s best-known old buildings and has accumulated local ghost lore alongside its National Register history. Check current operating status before routing visitors inside.', 'limited', 'https://www.strawberrypt.com/', null, 'America/Chicago', now()),
  ('Shrine of the Grotto of the Redemption', 'shrine-of-the-grotto-of-the-redemption', 'roadside-oddities', 42.96389, -94.44556, 'West Bend', 'IA', 'Nine interconnected grottos built from minerals, fossils, shells and petrified material create a monumental religious landscape unlike almost anything else in the Midwest. Construction began in 1912 and the site remains one of Iowa''s signature outsider-architecture destinations.', 'open', 'https://www.westbendgrotto.com/', null, 'America/Chicago', now()),
  ('Future Birthplace of Captain James T. Kirk', 'future-birthplace-of-captain-james-t-kirk', 'roadside-oddities', 41.4799, -91.5813, 'Riverside', 'IA', 'Riverside declared itself the future birthplace of Star Trek''s James T. Kirk after fans noticed his fictional Iowa origin. A small monument and themed displays turn an otherwise ordinary town into a pilgrimage point for science-fiction travelers.', 'open', 'https://www.riversideiowa.gov/', null, 'America/Chicago', now()),
  ('American Gothic House', 'american-gothic-house', 'roadside-oddities', 40.92139, -92.21401, 'Eldon', 'IA', 'Grant Wood used this small Carpenter Gothic house as the architectural backdrop for American Gothic. Visitors can see the actual house, use costume props at the adjacent center and recreate one of America''s most recognizable paintings.', 'open', 'https://americangothichouse.org/', null, 'America/Chicago', now()),
  ('Field of Dreams Movie Site', 'field-of-dreams-movie-site', 'roadside-oddities', 42.497, -91.0541, 'Dyersville', 'IA', 'The baseball diamond built for the 1989 film Field of Dreams still sits among Iowa cornfields. Visitors can walk the field, photograph the farmhouse and experience one of the country''s most recognizable movie locations.', 'open', 'https://www.fieldofdreamsmoviesite.com/', null, 'America/Chicago', now()),
  ('Surf Ballroom & Museum', 'surf-ballroom-museum', 'weird-history', 43.13987, -93.38967, 'Clear Lake', 'IA', 'The restored Surf Ballroom is famous as the final venue where Buddy Holly, Ritchie Valens and J.P. Richardson performed before their fatal 1959 plane crash. It remains an active concert venue and museum filled with music-history memorabilia.', 'open', 'https://www.surfballroom.com/', null, 'America/Chicago', now()),
  ('Buddy Holly Crash Site Memorial', 'buddy-holly-crash-site-memorial', 'weird-history', 43.22038, -93.38142, 'Clear Lake', 'IA', 'A memorial in a farm field marks the 1959 crash that killed Buddy Holly, Ritchie Valens, J.P. Richardson and pilot Roger Peterson. Reaching it requires a walk along an informal path between fields, so conditions can be muddy and visitors should stay on the established route.', 'limited', 'https://www.traveliowa.com/destination/buddy-holly-crash-site/', null, 'America/Chicago', now()),
  ('Buddy Holly Glasses Trailhead Marker', 'buddy-holly-glasses-trailhead-marker', 'roadside-oddities', 43.2159, -93.3748, 'Clear Lake', 'IA', 'A giant pair of black-framed glasses beside the road marks the walking route toward the Buddy Holly crash memorial. The oversized sculpture is a quick photo stop and a practical landmark for locating the field path.', 'roadside', 'https://www.traveliowa.com/destination/buddy-holly-crash-site/', null, 'America/Chicago', now()),
  ('Music Man Square', 'music-man-square', 'roadside-oddities', 43.1531, -93.1992, 'Mason City', 'IA', 'This attraction celebrates Mason City native Meredith Willson and The Music Man with a recreated 1912 streetscape, exhibits and Willson''s boyhood home. It turns the fictional River City into a physical Iowa destination.', 'limited', 'https://musicmansquare.org/', null, 'America/Chicago', now()),
  ('Snake Alley', 'snake-alley', 'roadside-oddities', 40.8071, -91.1137, 'Burlington', 'IA', 'Built in 1894, this brick street climbs a steep bluff through a series of tight switchbacks. Its exaggerated curves earned it national roadside fame and make it one of Iowa''s most recognizable unusual streets.', 'open', 'https://www.visitburlingtoniowa.com/', null, 'America/Chicago', now()),
  ('Matchstick Marvels Museum', 'matchstick-marvels-museum', 'museums', 42.1875, -92.7166, 'Gladbrook', 'IA', 'Artist Patrick Acton spent decades building enormous detailed sculptures from ordinary wooden matchsticks. The museum displays models ranging from famous architecture to large fantasy and pop-culture creations.', 'limited', 'https://matchstickmarvels.com/', null, 'America/Chicago', now()),
  ('Hobo Museum', 'hobo-museum', 'museums', 43.09643, -93.80137, 'Britt', 'IA', 'Britt''s Hobo Museum preserves artifacts, photographs, artwork and oral history connected with America''s hobo culture. The town also hosts the long-running National Hobo Convention, giving the museum a living connection to the tradition it documents.', 'limited', 'https://www.hobomuseum.org/', null, 'America/Chicago', now()),
  ('National Hobo Cemetery', 'national-hobo-cemetery', 'weird-history', 43.0889, -93.8075, 'Britt', 'IA', 'Evergreen Cemetery contains graves and memorials for well-known members of America''s hobo community, many identified by their road names. It is a distinctive piece of vernacular American history and should be visited with normal cemetery respect.', 'limited', 'https://www.hobomuseum.org/', null, 'America/Chicago', now()),
  ('Iowa 80 Trucking Museum', 'iowa-80-trucking-museum', 'museums', 41.62097, -90.78118, 'Walcott', 'IA', 'This free museum beside Interstate 80 preserves antique trucks, rare engines and artifacts spanning the history of long-haul transportation. Its collection is unusually specific and pairs naturally with the giant truck stop next door.', 'open', 'https://www.iowa80truckingmuseum.com/', null, 'America/Chicago', now()),
  ('Iowa 80 — World''s Largest Truckstop', 'iowa-80-worlds-largest-truckstop', 'roadside-oddities', 41.6178, -90.7803, 'Walcott', 'IA', 'What began as a small truck stop in 1964 has expanded into a sprawling roadside complex with restaurants, shops, services, displays and truck-focused attractions. Its enormous scale has made it a destination rather than merely a fuel stop.', 'open', 'https://iowa80truckstop.com/', null, 'America/Chicago', now()),
  ('Buffalo Bill Museum', 'buffalo-bill-museum', 'museums', 41.5982, -90.3422, 'Le Claire', 'IA', 'This riverfront museum covers William ''Buffalo Bill'' Cody, local Mississippi River history and unusual regional artifacts. One of its major objects is the preserved Lone Star steamboat, a National Historic Landmark.', 'limited', 'https://buffalobillmuseumleclaire.com/', null, 'America/Chicago', now()),
  ('Antique Archaeology', 'antique-archaeology', 'roadside-oddities', 41.5994, -90.3442, 'Le Claire', 'IA', 'The original Antique Archaeology shop is associated with the television series American Pickers and occupies a former fabrication property near the Mississippi River. Visitors can browse vintage signs, motorcycles and show-related memorabilia.', 'open', 'https://www.antiquearchaeology.com/', null, 'America/Chicago', now()),
  ('Maquoketa Caves State Park', 'maquoketa-caves-state-park', 'roadside-oddities', 42.12, -90.7667, 'Maquoketa', 'IA', 'Iowa''s best-known cave park contains a dense network of caverns, passages, sinkholes and natural bridges reached by hiking trails and stairways. Some caves require crawling or wading and may close seasonally for wildlife or safety reasons.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/maquoketa-caves-state-park', null, 'America/Chicago', now()),
  ('Crystal Lake Cave', 'crystal-lake-cave', 'roadside-oddities', 42.4597, -90.6854, 'Dubuque', 'IA', 'Discovered during nineteenth-century mining, Crystal Lake Cave contains stalactites, stalagmites and other mineral formations beneath the Dubuque area. Visitors enter only on scheduled commercial cave tours.', 'limited', 'https://crystallakecave.com/', null, 'America/Chicago', now()),
  ('Spook Cave', 'spook-cave', 'roadside-oddities', 43.0264, -91.2475, 'McGregor', 'IA', 'Visitors board small boats and travel directly into a flooded limestone cavern at this long-running northeast Iowa roadside attraction. The underground boat tour gives the site a classic mid-century tourist-stop feel.', 'limited', 'https://www.spookcave.com/', null, 'America/Chicago', now()),
  ('Ice Cave State Preserve', 'ice-cave-state-preserve', 'roadside-oddities', 43.3018, -91.7882, 'Decorah', 'IA', 'Cold air trapped within fractured limestone can preserve ice well into warm months inside this small natural cave near Decorah. The unusual temperature behavior led Iowa to protect the site as a state preserve.', 'open', 'https://www.iowadnr.gov/places-go/state-preserves', null, 'America/Chicago', now()),
  ('Fossil & Prairie Park Preserve', 'fossil-prairie-park-preserve', 'roadside-oddities', 43.0599, -92.9377, 'Rockford', 'IA', 'A former quarry exposes Devonian-age rock packed with brachiopods, corals and other fossils that visitors can search for and collect under park rules. Historic kilns and restored prairie add an industrial and ecological layer to the site.', 'open', 'https://www.fossilcenter.com/', null, 'America/Chicago', now()),
  ('Devonian Fossil Gorge', 'devonian-fossil-gorge', 'roadside-oddities', 41.7227, -91.5609, 'Coralville', 'IA', 'Floodwaters in 1993 and 2008 stripped away soil below Coralville Lake and exposed a broad pavement of roughly 375-million-year-old Devonian fossils. Visitors can walk through the ancient seafloor and see corals and marine remains in place.', 'open', 'https://www.mvr.usace.army.mil/Missions/Recreation/Coralville-Lake/', null, 'America/Chicago', now()),
  ('Mines of Spain Recreation Area', 'mines-of-spain-recreation-area', 'weird-history', 42.4695, -90.6769, 'Dubuque', 'IA', 'This large Mississippi River preserve protects landscapes tied to Indigenous history, early lead mining and trader Julien Dubuque. Trails connect bluffs, archaeological areas and the dramatic Dubuque monument.', 'open', 'https://www.minesofspain.org/', null, 'America/Chicago', now()),
  ('Julien Dubuque Monument', 'julien-dubuque-monument', 'roadside-oddities', 42.4666, -90.6637, 'Dubuque', 'IA', 'A stone tower resembling a small castle crowns a Mississippi River bluff above the burial place associated with trader Julien Dubuque. The monument is one of the most dramatic overlooks in eastern Iowa.', 'open', 'https://www.minesofspain.org/', null, 'America/Chicago', now()),
  ('Dubuque Shot Tower', 'dubuque-shot-tower', 'weird-history', 42.5103, -90.6549, 'Dubuque', 'IA', 'Built in 1856, this narrow stone-and-brick tower was used to manufacture lead shot by dropping molten lead from the top so it formed into spheres while falling. The surviving structure is a rare remnant of nineteenth-century industrial technology.', 'roadside', 'https://www.cityofdubuque.org/', null, 'America/Chicago', now()),
  ('Fenelon Place Elevator', 'fenelon-place-elevator', 'roadside-oddities', 42.5002, -90.6701, 'Dubuque', 'IA', 'This tiny funicular climbs the bluff above downtown Dubuque on an extremely short, steep track. Riders get a panoramic river view while experiencing one of the country''s most unusual pieces of urban transit.', 'limited', 'https://www.fenelonplaceelevator.com/', null, 'America/Chicago', now()),
  ('Pikes Peak State Park Overlook', 'pikes-peak-state-park-overlook', 'roadside-oddities', 42.9947, -91.1702, 'McGregor', 'IA', 'A high bluff overlook gives a sweeping view of the Mississippi and Wisconsin Rivers near their confluence. The park''s cliffs, ravines and archaeological history make it more than a standard scenic pull-off.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/pikes-peak-state-park', null, 'America/Chicago', now()),
  ('Effigy Mounds National Monument', 'effigy-mounds-national-monument', 'weird-history', 43.0883, -91.1877, 'Harpers Ferry', 'IA', 'More than 200 prehistoric mounds are preserved here, including numerous earthworks shaped like bears and birds. The landscape is culturally significant to multiple Indigenous nations and should be treated as a protected sacred archaeological site.', 'open', 'https://www.nps.gov/efmo/', null, 'America/Chicago', now()),
  ('Wildcat Den State Park', 'wildcat-den-state-park', 'roadside-oddities', 41.4788, -91.0717, 'Muscatine', 'IA', 'Trails wind through sandstone formations, narrow ravines and wooded bluffs with names such as Devil''s Punch Bowl and Fat Man''s Squeeze. The park combines strange erosion features with one of Iowa''s best-preserved historic mills.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/wildcat-den-state-park', null, 'America/Chicago', now()),
  ('Pine Creek Grist Mill', 'pine-creek-grist-mill', 'weird-history', 41.4891, -91.0575, 'Muscatine', 'IA', 'Built in the 1840s, Pine Creek Grist Mill is one of Iowa''s oldest operating-style grist mills and still preserves substantial original machinery. It stands inside Wildcat Den State Park beside the creek and sandstone landscape.', 'limited', 'https://pinecreekgristmill.com/', null, 'America/Chicago', now()),
  ('Backbone State Park', 'backbone-state-park', 'roadside-oddities', 42.5965, -91.5589, 'Dundee', 'IA', 'Iowa''s oldest state park is centered on a narrow ridge of exposed dolomite known as the Devil''s Backbone. Trails pass cliffs, caves, forest and stone structures built by the Civilian Conservation Corps.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/backbone-state-park', null, 'America/Chicago', now()),
  ('Devil''s Backbone Ridge', 'devils-backbone-ridge', 'folklore', 42.6055, -91.5608, 'Dundee', 'IA', 'The narrow rock spine that gave Backbone State Park its name forms a dramatic ridge above the Maquoketa River. Its devil-themed name and unusually rugged terrain make it a natural OddWay stop within the larger park.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/backbone-state-park', null, 'America/Chicago', now()),
  ('Ledges State Park Canyon', 'ledges-state-park-canyon', 'roadside-oddities', 41.9991, -93.8875, 'Madrid', 'IA', 'Pea''s Creek cuts through steep sandstone ledges and a narrow canyon crossed by a low road that can flood after heavy rain. The cliff walls and shallow stream crossings create one of central Iowa''s most unusual park landscapes.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/ledges-state-park', null, 'America/Chicago', now()),
  ('Dolliver Memorial State Park — Copperas Beds', 'dolliver-memorial-state-park-copperas-beds', 'roadside-oddities', 42.3647, -94.0089, 'Otho', 'IA', 'Sandstone cliffs and mineral-stained formations called the Copperas Beds line the Des Moines River valley in this wooded park. Trails also reach unusual erosional features and historic CCC structures.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/dolliver-memorial-state-park', null, 'America/Chicago', now()),
  ('Preparation Canyon State Park', 'preparation-canyon-state-park', 'weird-history', 41.9135, -95.9309, 'Moorhead', 'IA', 'This rugged Loess Hills park preserves land once associated with Preparation, a nineteenth-century Mormon splinter settlement that largely disappeared. Hiking trails now cross the hills where the short-lived community stood.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/preparation-canyon-state-park', null, 'America/Chicago', now()),
  ('Hitchcock Nature Center', 'hitchcock-nature-center', 'roadside-oddities', 41.4212, -95.8629, 'Honey Creek', 'IA', 'Trails and an observation tower overlook the deeply eroded Loess Hills, a globally unusual landscape made from windblown silt. The ridge system feels far more western and rugged than most visitors expect from Iowa.', 'open', 'https://www.pottconservation.com/parks-and-habitat-areas/hitchcock-nature-center/', null, 'America/Chicago', now()),
  ('Stone State Park', 'stone-state-park', 'roadside-oddities', 42.5736, -96.4766, 'Sioux City', 'IA', 'This park protects rugged Loess Hills ridges immediately outside Sioux City. Trails climb narrow prairie-topped spines with broad views over the Missouri River region.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/stone-state-park', null, 'America/Chicago', now()),
  ('Blood Run National Historic Landmark', 'blood-run-national-historic-landmark', 'weird-history', 43.4272, -96.4793, 'Larchwood', 'IA', 'Blood Run preserves part of a large Indigenous settlement and ceremonial landscape used for centuries along the Big Sioux River. Earthworks and archaeological remains make it one of the most important pre-contact sites in the region.', 'limited', 'https://history.iowa.gov/history/sites/blood-run', null, 'America/Chicago', now()),
  ('Toolesboro Mounds National Historic Landmark', 'toolesboro-mounds-national-historic-landmark', 'weird-history', 41.9678, -91.0124, 'Toolesboro', 'IA', 'Several large burial mounds remain from a Middle Woodland ceremonial complex built roughly 2,000 years ago. A small museum interprets the archaeology while the protected mounds remain visible outside.', 'limited', 'https://history.iowa.gov/history/sites/toolesboro-mounds', null, 'America/Chicago', now()),
  ('Glenwood Archaeological State Preserve', 'glenwood-archaeological-state-preserve', 'weird-history', 41.046, -95.7402, 'Glenwood', 'IA', 'The Glenwood area contains one of Iowa''s richest concentrations of prehistoric earth-lodge village sites associated with the Central Plains tradition. The preserve protects sensitive archaeological ground rather than operating as an unrestricted digging site.', 'limited', 'https://www.iowadnr.gov/places-go/state-preserves', null, 'America/Chicago', now()),
  ('Albert the Bull', 'albert-the-bull', 'roadside-oddities', 41.7218, -94.9287, 'Audubon', 'IA', 'A gigantic concrete Hereford bull towers over Audubon as a tribute to the area''s cattle industry. Albert has become one of Iowa''s classic oversized roadside mascots.', 'open', 'https://www.auduboniowa.org/', null, 'America/Chicago', now()),
  ('World''s Largest Wooden Nickel', 'worlds-largest-wooden-nickel', 'roadside-oddities', 41.6982, -91.5513, 'Iowa City', 'IA', 'An enormous painted wooden nickel stands beside a rural road north of Iowa City. Built as a political statement and roadside curiosity, it turns a familiar coin into a house-sized object.', 'roadside', 'https://www.roadsideamerica.com/tip/1862', null, 'America/Chicago', now()),
  ('Elwood the World''s Largest Concrete Gnome', 'elwood-the-worlds-largest-concrete-gnome', 'roadside-oddities', 42.0286, -93.6386, 'Ames', 'IA', 'Reiman Gardens is home to Elwood, a towering concrete garden gnome built at a scale large enough to qualify as a former world-record holder. The whimsical figure sits within the public botanical garden grounds.', 'open', 'https://www.reimangardens.com/', null, 'America/Chicago', now()),
  ('Giant Frying Pan', 'giant-frying-pan', 'roadside-oddities', 42.3152, -92.0042, 'Brandon', 'IA', 'Brandon displays a massive metal frying pan built as a roadside attraction and community landmark. It is a classic example of small-town America''s obsession with turning ordinary household objects into giant monuments.', 'roadside', 'https://www.roadsideamerica.com/tip/2358', null, 'America/Chicago', now()),
  ('Swedish Coffee Pot Water Tower', 'swedish-coffee-pot-water-tower', 'roadside-oddities', 40.982, -95.1045, 'Stanton', 'IA', 'Stanton''s former water tower was built in the shape of a giant Swedish coffee pot as a tribute to the community''s Scandinavian heritage. The oversized pot has been preserved as a town landmark even after leaving active water service.', 'roadside', 'https://www.stantoniowa.com/', null, 'America/Chicago', now()),
  ('Swedish Coffee Cup Water Tower', 'swedish-coffee-cup-water-tower', 'roadside-oddities', 40.9811, -95.1029, 'Stanton', 'IA', 'After the coffee-pot tower became a local icon, Stanton continued the theme with a huge cup-and-saucer water tower. Together the pair create one of Iowa''s strangest municipal utility landmarks.', 'roadside', 'https://www.stantoniowa.com/', null, 'America/Chicago', now()),
  ('Danish Windmill', 'danish-windmill', 'roadside-oddities', 41.5933, -95.0605, 'Elk Horn', 'IA', 'A nineteenth-century Danish windmill was dismantled in Denmark, shipped to Iowa and rebuilt in Elk Horn. It now serves as an operating cultural landmark and museum for the area''s Danish heritage.', 'open', 'https://www.danishwindmill.com/', null, 'America/Chicago', now()),
  ('The Freedom Rock', 'the-freedom-rock', 'roadside-oddities', 41.5208, -94.4054, 'Menlo', 'IA', 'Artist Ray ''Bubba'' Sorensen repaints this enormous roadside boulder each year with detailed military and veterans-themed scenes. The original Menlo rock inspired a statewide project placing painted Freedom Rocks in every Iowa county.', 'open', 'https://www.thefreedomrock.com/', null, 'America/Chicago', now()),
  ('High Trestle Trail Bridge', 'high-trestle-trail-bridge', 'roadside-oddities', 41.8298, -93.9439, 'Madrid', 'IA', 'A half-mile trail bridge spans the Des Moines River valley inside a series of twisting steel frames meant to evoke passage through a mine shaft. At night blue lighting transforms the structure into one of Iowa''s most surreal public works.', 'open', 'https://www.inhf.org/what-we-do/protection/high-trestle-trail/', null, 'America/Chicago', now()),
  ('Pappajohn Sculpture Park', 'pappajohn-sculpture-park', 'roadside-oddities', 41.5853, -93.6368, 'Des Moines', 'IA', 'More than two dozen major contemporary sculptures occupy an open downtown park, including monumental works by internationally known artists. The oversized forms make the park feel like an outdoor cabinet of strange modern objects.', 'open', 'https://desmoinesartcenter.org/art/pappajohn-sculpture-park/', null, 'America/Chicago', now()),
  ('Maharishi Vedic Observatory', 'maharishi-vedic-observatory', 'roadside-oddities', 41.0173, -91.9671, 'Fairfield', 'IA', 'This open-air observatory uses stone and geometric instruments inspired by ancient Indian astronomical traditions rather than modern telescopes. It reflects Fairfield''s unusual role as an American center for Transcendental Meditation and Vedic architecture.', 'limited', 'https://www.miu.edu/', null, 'America/Chicago', now()),
  ('Maharishi Golden Domes', 'maharishi-golden-domes', 'roadside-oddities', 41.0179, -91.9659, 'Fairfield', 'IA', 'Two large gold-colored meditation domes on the Maharishi International University campus are among Fairfield''s most visually distinctive structures. Access to interiors depends on university rules and events.', 'limited', 'https://www.miu.edu/', null, 'America/Chicago', now()),
  ('Hotel Pattee', 'hotel-pattee', 'roadside-oddities', 41.8395, -94.1072, 'Perry', 'IA', 'This historic hotel is filled with individually themed rooms celebrating Iowa people, towns and traditions. The elaborate interiors make an overnight stay feel closer to sleeping inside a regional museum.', 'open', 'https://hotelpattee.com/', null, 'America/Chicago', now()),
  ('Bily Clocks Museum', 'bily-clocks-museum', 'museums', 43.2027, -91.952, 'Spillville', 'IA', 'Brothers Frank and Joseph Bily carved astonishingly elaborate wooden clocks, many filled with moving figures, patriotic scenes and miniature architecture. Their collection fills a small museum in Spillville alongside Antonín Dvořák history.', 'limited', 'https://www.bilyclocks.org/', null, 'America/Chicago', now()),
  ('Vesterheim Norwegian-American Museum', 'vesterheim-norwegian-american-museum', 'museums', 43.3047, -91.7857, 'Decorah', 'IA', 'Vesterheim preserves carved furniture, folk art, immigrant artifacts and historic buildings tied to Norwegian-American life. Its collection includes highly ornate objects that make it more visually unusual than a standard local history museum.', 'open', 'https://vesterheim.org/', null, 'America/Chicago', now()),
  ('National Farm Toy Museum', 'national-farm-toy-museum', 'museums', 42.4807, -91.119, 'Dyersville', 'IA', 'Thousands of miniature tractors, farm implements and agricultural toys trace the strange and surprisingly deep history of farm-model collecting. The museum is a natural OddWay stop in a town already famous for baseball and farm culture.', 'open', 'https://www.nationalfarmtoymuseum.com/', null, 'America/Chicago', now()),
  ('University of Iowa Museum of Natural History', 'university-of-iowa-museum-of-natural-history', 'museums', 41.6623, -91.5358, 'Iowa City', 'IA', 'Iowa''s oldest university museum combines fossils, taxidermy, geology and large natural-history specimens inside historic Macbride Hall. Its old-school display style gives it the feel of a classic cabinet museum.', 'open', 'https://mnh.uiowa.edu/', null, 'America/Chicago', now()),
  ('Sanford Museum & Planetarium', 'sanford-museum-planetarium', 'museums', 42.7508, -95.5517, 'Cherokee', 'IA', 'This unusually broad small-city museum combines archaeology, geology, regional history and astronomy beneath one roof. Its planetarium and strong archaeological collections give it more range than most local museums.', 'open', 'https://sanfordmuseum.org/', null, 'America/Chicago', now()),
  ('Sergeant Floyd Monument', 'sergeant-floyd-monument', 'weird-history', 42.4907, -96.4163, 'Sioux City', 'IA', 'A tall stone obelisk marks the burial place of Sergeant Charles Floyd, the only member of the Lewis and Clark Expedition to die during the journey. The monument became the first property designated a National Historic Landmark in the United States.', 'open', 'https://www.nps.gov/places/sergeant-floyd-monument.htm', null, 'America/Chicago', now()),
  ('Trinity Heights', 'trinity-heights', 'roadside-oddities', 42.5073, -96.4028, 'Sioux City', 'IA', 'This hilltop religious complex contains enormous statues of Jesus and Mary, shrines, chapels and devotional gardens. The monumental scale makes it one of western Iowa''s most visually unusual sacred spaces.', 'open', 'https://trinityheights.com/', null, 'America/Chicago', now()),
  ('Sergeant Floyd River Museum — M.V. Sergeant Floyd', 'sergeant-floyd-river-museum-mv-sergeant-floyd', 'museums', 42.4966, -96.4147, 'Sioux City', 'IA', 'A decommissioned U.S. Army Corps of Engineers inspection vessel now serves as a floating museum beside the Missouri River. Visitors can walk through the ship while learning about river travel and Lewis and Clark history.', 'open', 'https://www.siouxcitymuseum.org/sergeant-floyd-river-museum', null, 'America/Chicago', now()),
  ('Museum of Danish America', 'museum-of-danish-america', 'museums', 41.5905, -95.0544, 'Elk Horn', 'IA', 'This national museum explores Danish immigration through artifacts, folk traditions, temporary exhibitions and outdoor heritage spaces. Its prairie setting and specialized collection pair well with Elk Horn''s transplanted Danish windmill.', 'open', 'https://www.danishmuseum.org/', null, 'America/Chicago', now()),
  ('Vermeer Mill', 'vermeer-mill', 'roadside-oddities', 41.4076, -92.9166, 'Pella', 'IA', 'This towering working Dutch windmill rises above Pella and contains a functional grain-milling system. Guided access lets visitors climb through the machinery and see how a traditional European mill works.', 'limited', 'https://www.pellahistorical.org/', null, 'America/Chicago', now()),
  ('Pella Klokkenspel', 'pella-klokkenspel', 'roadside-oddities', 41.4088, -92.9161, 'Pella', 'IA', 'Mechanical figures emerge from this downtown clock installation to perform short scenes connected with Pella''s Dutch heritage. The moving characters make an ordinary streetscape suddenly behave like an oversized music box.', 'open', 'https://www.pella.org/', null, 'America/Chicago', now()),
  ('Amana Heritage Museum', 'amana-heritage-museum', 'weird-history', 41.7993, -91.8698, 'Amana', 'IA', 'The museum preserves the story of the communal religious society that founded the Amana Colonies and operated a highly organized shared economy for decades. Historic buildings and artifacts explain a social experiment that still shapes the villages today.', 'limited', 'https://amanaheritage.org/', null, 'America/Chicago', now()),
  ('Amana Woolen Mill', 'amana-woolen-mill', 'weird-history', 41.802, -91.8679, 'Amana', 'IA', 'Textile manufacturing has continued in Amana since the communal era, and the woolen mill remains part of that unusual industrial tradition. Visitors can see a working business rooted directly in the colony''s nineteenth-century economy.', 'open', 'https://www.amanawoolenmill.com/', null, 'America/Chicago', now()),
  ('Herbert Hoover Birthplace Cottage', 'herbert-hoover-birthplace-cottage', 'weird-history', 41.6711, -91.3463, 'West Branch', 'IA', 'The future president was born in this tiny two-room cottage in 1874. Its extreme simplicity contrasts sharply with Hoover''s later global career and makes the preserved house a compact historical oddity.', 'open', 'https://www.nps.gov/heho/', null, 'America/Chicago', now()),
  ('Arnolds Park — The Legend Roller Coaster', 'arnolds-park-the-legend-roller-coaster', 'roadside-oddities', 43.3653, -95.1312, 'Arnolds Park', 'IA', 'The wooden Legend roller coaster dates to 1930 and remains the signature ride of one of America''s oldest amusement parks. Its lakeside setting and traditional wood construction preserve an increasingly rare form of amusement history.', 'limited', 'https://arnoldspark.com/', null, 'America/Chicago', now()),
  ('Okoboji Classic Cars', 'okoboji-classic-cars', 'museums', 43.3222, -95.1498, 'Milford', 'IA', 'Classic cars are displayed inside elaborate recreations of old streets, storefronts and period scenes rather than a plain warehouse. The immersive staging turns the collection into an indoor nostalgic town.', 'limited', 'https://okobojiclassiccars.com/', null, 'America/Chicago', now()),
  ('The Fort Museum & Frontier Village', 'the-fort-museum-frontier-village', 'museums', 42.5032, -94.195, 'Fort Dodge', 'IA', 'A reconstructed frontier fort and village bring together military buildings, pioneer structures and local artifacts. The sprawling complex feels like a preserved nineteenth-century settlement assembled inside modern Fort Dodge.', 'limited', 'https://fortmuseumfv.com/', null, 'America/Chicago', now()),
  ('Kate Shelley High Bridge', 'kate-shelley-high-bridge', 'roadside-oddities', 42.055, -93.9891, 'Boone', 'IA', 'A massive railroad bridge spans the Des Moines River valley near the site associated with Kate Shelley''s famous 1881 rescue story. The current bridge remains active railroad infrastructure, so OddWay travelers should view only from lawful public locations and never enter the tracks.', 'roadside', 'https://www.boonehistorymuseums.org/', null, 'America/Chicago', now()),
  ('Boone & Scenic Valley Railroad', 'boone-scenic-valley-railroad', 'roadside-oddities', 42.0595, -93.8808, 'Boone', 'IA', 'Historic trains carry visitors across the Des Moines River valley on former interurban and railroad routes. Steam, diesel and excursion equipment make the site a moving museum of Iowa rail history.', 'limited', 'https://bsvrr.com/', null, 'America/Chicago', now()),
  ('Mamie Doud Eisenhower Birthplace', 'mamie-doud-eisenhower-birthplace', 'weird-history', 42.059, -93.8795, 'Boone', 'IA', 'The restored house where future First Lady Mamie Doud Eisenhower was born preserves late-nineteenth-century domestic life and family material. Its connection to the Eisenhower presidency makes the small Boone house an unexpectedly national historic stop.', 'limited', 'https://www.boonehistorymuseums.org/', null, 'America/Chicago', now()),
  ('John Wayne Birthplace & Museum', 'john-wayne-birthplace-museum', 'roadside-oddities', 41.3348, -94.0139, 'Winterset', 'IA', 'John Wayne was born Marion Morrison in this small Winterset house. The adjacent museum displays costumes, posters and memorabilia tied to one of Hollywood''s most recognizable screen figures.', 'open', 'https://www.johnwaynebirthplace.museum/', null, 'America/Chicago', now()),
  ('Roseman Covered Bridge', 'roseman-covered-bridge', 'roadside-oddities', 41.3625, -94.1618, 'Winterset', 'IA', 'This 1883 covered bridge became internationally recognizable through The Bridges of Madison County. Its isolated rural setting and preserved wooden structure make it the most cinematic of Madison County''s surviving bridges.', 'open', 'https://www.madisoncounty.com/the-covered-bridges/', null, 'America/Chicago', now()),
  ('Holliwell Covered Bridge', 'holliwell-covered-bridge', 'roadside-oddities', 41.3278, -93.9866, 'Winterset', 'IA', 'The longest of Madison County''s surviving covered bridges stretches across the Middle River southeast of Winterset. Its bright timber enclosure is preserved as a pedestrian and photo destination.', 'open', 'https://www.madisoncounty.com/the-covered-bridges/', null, 'America/Chicago', now()),
  ('Cedar Covered Bridge', 'cedar-covered-bridge', 'roadside-oddities', 41.4073, -93.9847, 'Winterset', 'IA', 'A reconstructed covered bridge stands at the site of one of Madison County''s historic spans. The bridge has been rebuilt after destructive fires, giving the location an unusual history of repeated loss and restoration.', 'open', 'https://www.madisoncounty.com/the-covered-bridges/', null, 'America/Chicago', now()),
  ('Hogback Covered Bridge', 'hogback-covered-bridge', 'roadside-oddities', 41.4176, -94.1108, 'Winterset', 'IA', 'Built in 1880, Hogback crosses the North River beneath a steep ridge that gave the bridge its name. The remote setting makes it one of the most atmospheric surviving Madison County bridges.', 'open', 'https://www.madisoncounty.com/the-covered-bridges/', null, 'America/Chicago', now()),
  ('Imes Covered Bridge', 'imes-covered-bridge', 'roadside-oddities', 41.2885, -93.8092, 'St. Charles', 'IA', 'Originally built in 1870, Imes is the oldest surviving covered bridge associated with Madison County. It now stands in a public park as a preserved pedestrian landmark.', 'open', 'https://www.madisoncounty.com/the-covered-bridges/', null, 'America/Chicago', now()),
  ('Cutler-Donahoe Covered Bridge', 'cutler-donahoe-covered-bridge', 'roadside-oddities', 41.3311, -94.0104, 'Winterset', 'IA', 'This nineteenth-century covered bridge was moved to Winterset City Park for preservation. Visitors can walk through the enclosed timber span while exploring several other unusual park structures nearby.', 'open', 'https://www.madisoncounty.com/the-covered-bridges/', null, 'America/Chicago', now()),
  ('Clark Tower', 'clark-tower', 'roadside-oddities', 41.3206, -94.0249, 'Winterset', 'IA', 'A rough-stone memorial tower rises from the wooded hills of Winterset City Park like a small medieval ruin. Built in the 1920s, it offers views over Madison County and looks deliberately older than it is.', 'open', 'https://www.winterset.gov/', null, 'America/Chicago', now()),
  ('Glenn Miller Birthplace Museum', 'glenn-miller-birthplace-museum', 'weird-history', 40.7398, -95.0366, 'Clarinda', 'IA', 'The birthplace of big-band leader Glenn Miller is preserved beside a museum devoted to his life, recordings and wartime service. The site anchors an unexpectedly major piece of American music history in southwest Iowa.', 'limited', 'https://www.glennmiller.org/', null, 'America/Chicago', now()),
  ('Donna Reed Heritage Museum', 'donna-reed-heritage-museum', 'roadside-oddities', 42.0177, -95.3556, 'Denison', 'IA', 'Denison celebrates hometown actor Donna Reed with costumes, photographs and memorabilia connected with her film and television career. The museum occupies part of the historic downtown theater complex bearing her name.', 'limited', 'https://donnareed.org/', null, 'America/Chicago', now()),
  ('Johnny Carson Birthplace', 'johnny-carson-birthplace', 'roadside-oddities', 40.989, -94.7386, 'Corning', 'IA', 'Late-night television host Johnny Carson was born in this modest Corning house. The property has been preserved by a local foundation and opens on scheduled dates rather than operating as an unrestricted attraction.', 'limited', 'https://johnnycarsonbirthplace.com/', null, 'America/Chicago', now()),
  ('Canteen Lunch in the Alley', 'canteen-lunch-in-the-alley', 'weird-history', 41.0188, -92.4145, 'Ottumwa', 'IA', 'This tiny diner is famous for loose-meat sandwiches and a horseshoe-shaped counter squeezed into a narrow downtown building. Its alley entrance and nearly unchanged interior make eating there feel like stepping into a preserved roadside-food time capsule.', 'open', 'https://www.canteenottumwa.com/', null, 'America/Chicago', now()),
  ('Wilton Candy Kitchen', 'wilton-candy-kitchen', 'weird-history', 41.5886, -91.0168, 'Wilton', 'IA', 'Operating since the nineteenth century, this historic soda fountain preserves old counters, fixtures and small-town confectionery traditions. It is one of Iowa''s best surviving examples of an old-fashioned candy and ice-cream shop.', 'open', 'https://wiltoncandykitchen.com/', null, 'America/Chicago', now()),
  ('Breitbach''s Country Dining', 'breitbachs-country-dining', 'weird-history', 42.6381, -90.8682, 'Balltown', 'IA', 'One of Iowa''s oldest continuously operating food traditions survives in tiny Balltown, where Breitbach''s has rebuilt after devastating fires and continued serving generations of travelers. The hilltop setting overlooks the Mississippi River country.', 'open', 'https://www.breitbachscountrydining.com/', null, 'America/Chicago', now()),
  ('Muscatine History and Industry Center — Pearl Button Story', 'muscatine-history-and-industry-center-pearl-button-story', 'weird-history', 41.4238, -91.0435, 'Muscatine', 'IA', 'Muscatine once dominated the world''s pearl-button industry by cutting blanks from freshwater mussel shells pulled from the Mississippi. Exhibits preserve the machines, shells and strange industrial process that turned the city into the ''Pearl Button Capital of the World.''', 'open', 'https://muscatinehistory.org/', null, 'America/Chicago', now()),
  ('German Hausbarn', 'german-hausbarn', 'roadside-oddities', 41.9098, -95.0646, 'Manning', 'IA', 'A traditional German Hausbarn combines living quarters and agricultural space beneath one roof. The structure was brought from Schleswig-Holstein and reconstructed in Iowa as a rare example of old-world rural architecture.', 'limited', 'https://www.manningia.com/', null, 'America/Chicago', now()),
  ('Motor Mill Historic Site', 'motor-mill-historic-site', 'weird-history', 42.8418, -91.3558, 'Elkader', 'IA', 'A towering six-story limestone grist mill stands beside the Turkey River with several associated nineteenth-century buildings. The isolated stone complex looks almost fortress-like in the wooded valley.', 'open', 'https://www.claytoncountyconservation.org/motor-mill-historic-site', null, 'America/Chicago', now()),
  ('Montauk Historic Site', 'montauk-historic-site', 'weird-history', 43.0026, -91.6492, 'Clermont', 'IA', 'The mansion of Iowa governor William Larrabee preserves ornate nineteenth-century interiors, collections and political history on a hill above Clermont. Its intact furnishings make the house feel unusually frozen in time.', 'limited', 'https://history.iowa.gov/history/sites/montauk', null, 'America/Chicago', now()),
  ('Cedar Rock — Frank Lloyd Wright Lowell Walter House', 'cedar-rock-frank-lloyd-wright-lowell-walter-house', 'roadside-oddities', 42.3968, -91.7698, 'Quasqueton', 'IA', 'Frank Lloyd Wright designed this Usonian house with custom furniture, river views and an unusually complete interior scheme. Visitors reach the house through scheduled tours at a state historic site.', 'limited', 'https://friendsofcedarrock.org/', null, 'America/Chicago', now()),
  ('Stockman House', 'stockman-house', 'roadside-oddities', 43.1518, -93.1946, 'Mason City', 'IA', 'This 1908 Frank Lloyd Wright house demonstrates Prairie School design on a compact residential scale. The structure was moved to save it from demolition and now operates as a museum.', 'limited', 'https://wrightonthepark.org/', null, 'America/Chicago', now()),
  ('Historic Park Inn', 'historic-park-inn', 'roadside-oddities', 43.1528, -93.201, 'Mason City', 'IA', 'The last remaining hotel in the world designed by Frank Lloyd Wright still operates in downtown Mason City. Guests can stay inside a functioning piece of Prairie School architecture rather than merely touring it.', 'open', 'https://historicparkinn.com/', null, 'America/Chicago', now()),
  ('Grant Wood Studio', 'grant-wood-studio', 'roadside-oddities', 41.9867, -91.6685, 'Cedar Rapids', 'IA', 'Grant Wood lived and worked in this converted carriage-house studio and painted several major works here. The compact interior preserves the artist''s hand-built details and gives American Gothic a second physical Iowa connection.', 'limited', 'https://www.crma.org/grant-wood-studio/', null, 'America/Chicago', now()),
  ('Brucemore', 'brucemore', 'roadside-oddities', 42.0088, -91.6424, 'Cedar Rapids', 'IA', 'A 26-acre estate surrounds a grand Queen Anne mansion with layered stories of industrial wealth, servants, animals and Cedar Rapids social history. Scheduled tours reveal unusual rooms and family collections.', 'limited', 'https://www.brucemore.org/', null, 'America/Chicago', now()),
  ('Dubuque Arboretum Japanese Garden', 'dubuque-arboretum-japanese-garden', 'roadside-oddities', 42.5317, -90.7208, 'Dubuque', 'IA', 'Within a large free public arboretum is a carefully designed Japanese garden with bridges, water, stonework and sculpted plantings. It is an unexpectedly elaborate hidden landscape on the city''s edge.', 'open', 'https://dubuquearboretum.net/', null, 'America/Chicago', now()),
  ('National Mississippi River Museum & Aquarium — Historic Vessels', 'national-mississippi-river-museum-aquarium-historic-vessels', 'museums', 42.4963, -90.6598, 'Dubuque', 'IA', 'Beyond aquariums, the museum complex preserves historic river vessels and industrial spaces tied to Mississippi navigation. Boarding full-size boats makes the site feel more like a working river-history campus than a standard museum.', 'open', 'https://www.rivermuseum.org/', null, 'America/Chicago', now()),
  ('Lock and Dam No. 11 Observation Area', 'lock-and-dam-no-11-observation-area', 'roadside-oddities', 42.539, -90.6465, 'Dubuque', 'IA', 'Visitors can watch enormous barges and towboats pass through a working Mississippi River lock. The scale of the gates, chambers and river traffic turns everyday infrastructure into an unexpectedly compelling mechanical stop.', 'open', 'https://www.mvr.usace.army.mil/Missions/Recreation/Mississippi-River-Project/', null, 'America/Chicago', now()),
  ('Keokuk Lock and Dam No. 19', 'keokuk-lock-and-dam-no-19', 'roadside-oddities', 40.3978, -91.3784, 'Keokuk', 'IA', 'The massive hydroelectric and navigation complex at Keokuk dramatically alters the Mississippi River and has operated for more than a century. Public viewpoints allow travelers to see industrial-scale river engineering without entering restricted facilities.', 'roadside', 'https://www.keokukiowa.gov/', null, 'America/Chicago', now()),
  ('Geode State Park', 'geode-state-park', 'roadside-oddities', 40.8244, -91.3806, 'Danville', 'IA', 'Named for Iowa''s state rock, this park sits in a region famous for geodes—hollow mineral nodules lined with crystals. Collecting rules vary by location, so the park itself is best treated as a geological landscape rather than a free-for-all digging site.', 'open', 'https://www.iowadnr.gov/places-go/state-parks/all-parks/geode-state-park', null, 'America/Chicago', now()),
  ('Bentonsport Historic District', 'bentonsport-historic-district', 'weird-history', 40.7213, -91.8537, 'Bentonsport', 'IA', 'A remarkably intact nineteenth-century river village survives along the Des Moines River with old storefronts, homes, bridges and ruins. The quiet streets feel like a commercial town that time simply moved around.', 'open', 'https://villagesofvanburen.com/', null, 'America/Chicago', now()),
  ('Bentonsport Iron Bridge', 'bentonsport-iron-bridge', 'roadside-oddities', 40.7221, -91.852, 'Bentonsport', 'IA', 'This nineteenth-century iron truss bridge now carries pedestrians across the Des Moines River between Bentonsport and Vernon. Its skeletal metal framework creates a strong visual centerpiece for the historic village.', 'open', 'https://villagesofvanburen.com/', null, 'America/Chicago', now()),
  ('Bonaparte Historic Riverfront', 'bonaparte-historic-riverfront', 'weird-history', 40.699, -91.8026, 'Bonaparte', 'IA', 'Tiny Bonaparte preserves blocks of nineteenth-century commercial buildings beside the Des Moines River, many dating to the town''s milling era. The unusually intact streetscape feels like a near-ghost-town without actually being abandoned.', 'open', 'https://villagesofvanburen.com/', null, 'America/Chicago', now()),
  ('Keosauqua Bentonsport Area — Pearson House', 'keosauqua-bentonsport-area-pearson-house', 'weird-history', 40.7302, -91.963, 'Keosauqua', 'IA', 'The Pearson House preserves local Underground Railroad history and nineteenth-century life in Van Buren County. Its hidden-escape associations add a serious layer of clandestine history to the river villages region.', 'limited', 'https://villagesofvanburen.com/', null, 'America/Chicago', now()),
  ('Hawkeye Point', 'hawkeye-point', 'roadside-oddities', 43.4602, -95.7086, 'Sibley', 'IA', 'Iowa''s highest natural point sits in an otherwise gently rolling agricultural landscape and is marked with signs, displays and a viewing area. The understated setting makes the state''s summit an amusing contrast to more dramatic high points elsewhere.', 'open', 'https://www.osceolacountyia.gov/', null, 'America/Chicago', now()),
  ('Lowest Point of Iowa — Mississippi River at Keokuk', 'lowest-point-of-iowa-mississippi-river-at-keokuk', 'roadside-oddities', 40.375, -91.377, 'Keokuk', 'IA', 'Iowa''s lowest elevation occurs where the Mississippi River exits the state near Keokuk. There is no dramatic summit marker, but the location gives OddWay travelers a geographic counterpart to Hawkeye Point.', 'roadside', 'https://www.iihr.uiowa.edu/', null, 'America/Chicago', now()),
  ('Sioux City Lewis and Clark Interpretive Center — Animatronic Exhibits', 'sioux-city-lewis-and-clark-interpretive-center-animatronic-exhibits', 'museums', 42.4952, -96.4154, 'Sioux City', 'IA', 'Life-size figures, mechanical displays and immersive scenes interpret the Lewis and Clark expedition beside the Missouri River. Its theatrical presentation makes the history feel more like a staged environment than a traditional museum gallery.', 'open', 'https://www.siouxcitylcic.com/', null, 'America/Chicago', now()),
  ('Iowa Gold Star Military Museum — Sherman Tank & Aircraft Displays', 'iowa-gold-star-military-museum-sherman-tank-aircraft-displays', 'museums', 41.7039, -93.7087, 'Johnston', 'IA', 'The Iowa National Guard museum displays armored vehicles, aircraft and military artifacts at Camp Dodge. Access procedures can change because the museum is on an active military installation, so visitors should check requirements before routing there.', 'limited', 'https://www.goldstarmuseum.iowa.gov/', null, 'America/Chicago', now()),
  ('State Historical Museum of Iowa — Mastodon & Curiosity Collections', 'state-historical-museum-of-iowa-mastodon-curiosity-collections', 'museums', 41.5907, -93.6178, 'Des Moines', 'IA', 'Iowa''s state history museum mixes political artifacts with archaeology, natural-history material and objects from everyday life across the state. Its larger collections provide context for many of OddWay''s stranger Iowa stories.', 'open', 'https://history.iowa.gov/history/museum', null, 'America/Chicago', now()),
  ('Iowa State Capitol — West Terrace & Golden Dome', 'iowa-state-capitol-west-terrace-golden-dome', 'roadside-oddities', 41.5912, -93.6038, 'Des Moines', 'IA', 'Iowa''s capitol is crowned by a huge 23-karat gold-leaf central dome and four smaller domes, creating one of the Midwest''s most extravagant statehouses. Interior tours reveal ornate staircases, mosaics and a vast law library.', 'open', 'https://www.legis.iowa.gov/resources/tourCapitol', null, 'America/Chicago', now()),
  ('Law Library at the Iowa State Capitol', 'law-library-at-the-iowa-state-capitol', 'roadside-oddities', 41.5911, -93.6035, 'Des Moines', 'IA', 'Inside the Capitol, a spectacular multi-level law library is lined with spiral staircases, ornate ironwork and packed book balconies. It looks more like a fantasy film set than a working government library.', 'limited', 'https://www.legis.iowa.gov/resources/tourCapitol', null, 'America/Chicago', now()),
  ('Salisbury House & Gardens', 'salisbury-house-gardens', 'roadside-oddities', 41.5886, -93.679, 'Des Moines', 'IA', 'This 1920s mansion was modeled after a fifteenth-century English manor and filled with old books, art, carved wood and imported architectural fragments. The building deliberately creates a piece of Tudor England in Iowa.', 'limited', 'https://salisburyhouse.org/', null, 'America/Chicago', now()),
  ('Terrace Hill', 'terrace-hill', 'roadside-oddities', 41.5836, -93.6493, 'Des Moines', 'IA', 'The Iowa governor''s residence occupies an elaborate 1869 Second Empire mansion with a towering central tower and ornate interiors. Guided tours reveal one of the state''s most extravagant surviving homes.', 'limited', 'https://terracehill.iowa.gov/', null, 'America/Chicago', now()),
  ('Jordan House', 'jordan-house', 'weird-history', 41.5867, -93.7484, 'West Des Moines', 'IA', 'The Jordan House was a documented Underground Railroad stop and home of abolitionist James C. Jordan. Guided visits connect the suburban mansion to secret movement of freedom seekers before the Civil War.', 'limited', 'https://www.wdmhs.org/jordan-house/', null, 'America/Chicago', now()),
  ('Iowa Aviation Museum', 'iowa-aviation-museum', 'museums', 41.3094, -94.4451, 'Greenfield', 'IA', 'Historic aircraft, engines and aviation artifacts fill this small museum at Greenfield''s airport. The collection also honors Iowa aviators and preserves machines that look especially strange at close range.', 'limited', 'https://www.flyingmuseum.com/', null, 'America/Chicago', now()),
  ('Dvorak Memorial & Spillville Clock Connection', 'dvorak-memorial-spillville-clock-connection', 'weird-history', 43.2016, -91.9523, 'Spillville', 'IA', 'Composer Antonín Dvořák spent the summer of 1893 in tiny Spillville, where the Czech-American community influenced some of his best-known American-period work. Memorials around town pair naturally with the Bily Clocks Museum.', 'open', 'https://www.bilyclocks.org/', null, 'America/Chicago', now()),
  ('Czech Village / New Bohemia Clock Tower', 'czech-village-new-bohemia-clock-tower', 'roadside-oddities', 41.9661, -91.6581, 'Cedar Rapids', 'IA', 'The Czech Village and New Bohemia district uses public art, clocks and restored immigrant-era buildings to preserve Cedar Rapids'' Czech and Slovak identity. The streetscape makes a distinctive walkable cultural stop near the national museum.', 'open', 'https://www.czechvillagecedarrapids.com/', null, 'America/Chicago', now()),
  ('National Czech & Slovak Museum & Library', 'national-czech-slovak-museum-library', 'museums', 41.9647, -91.66, 'Cedar Rapids', 'IA', 'This national museum preserves folk costumes, political artifacts, immigrant objects and material connected with Czech and Slovak history. The building itself was moved and expanded after the catastrophic 2008 Cedar River flood.', 'open', 'https://www.ncsml.org/', null, 'America/Chicago', now()),
  ('Iowa Quilt Museum', 'iowa-quilt-museum', 'museums', 41.3338, -94.0134, 'Winterset', 'IA', 'A museum devoted entirely to quilts rotates exhibitions of elaborate textile art, historic patterns and contemporary work. Its unusually narrow collecting focus makes it a strong niche-museum stop in Winterset.', 'open', 'https://www.iowaquiltmuseum.org/', null, 'America/Chicago', now()),
  ('Raccoon River Valley Trail — Waukee Railroad Sculpture', 'raccoon-river-valley-trail-waukee-railroad-sculpture', 'roadside-oddities', 41.6112, -93.8862, 'Waukee', 'IA', 'Rail-themed sculpture and trail infrastructure mark Waukee''s connection to the former railroad corridor now used by cyclists and pedestrians. It is a compact transportation-history stop along one of central Iowa''s major trails.', 'open', 'https://raccoonrivervalleytrail.org/', null, 'America/Chicago', now()),
  ('Carroll Depot & Railroad Museum', 'carroll-depot-railroad-museum', 'weird-history', 42.0652, -94.8664, 'Carroll', 'IA', 'A restored railroad depot preserves passenger-era architecture and artifacts from the lines that helped build western Iowa towns. The historic platform and trackside setting make it more tangible than a conventional local museum.', 'limited', 'https://www.carrolliowa.com/', null, 'America/Chicago', now()),
  ('Carnegie-Stout Public Library Ghost Lore', 'carnegie-stout-public-library-ghost-lore', 'haunted', 42.5007, -90.6726, 'Dubuque', 'IA', 'Dubuque''s historic Carnegie-Stout library has long been associated with staff stories of unexplained movement, sounds and apparitions. It remains a functioning public library, so OddWay should present the supernatural claims as local lore rather than fact.', 'open', 'https://carnegiestout.org/', null, 'America/Chicago', now()),
  ('Hotel Julien Dubuque', 'hotel-julien-dubuque', 'haunted', 42.4968, -90.6655, 'Dubuque', 'IA', 'The historic Hotel Julien occupies a long-standing downtown hotel site associated with river-town history, famous guests and local ghost stories. It remains an operating hotel, giving travelers a lawful way to experience the atmospheric building.', 'open', 'https://hoteljuliendubuque.com/', null, 'America/Chicago', now()),
  ('Mathias Ham Historic Site', 'mathias-ham-historic-site', 'haunted', 42.5157, -90.6672, 'Dubuque', 'IA', 'This 1850s riverfront mansion preserves the life of businessman Mathias Ham and Dubuque''s early settlement era. Local paranormal stories have grown around the house, while official access remains through museum tours and events.', 'limited', 'https://www.rivermuseum.org/', null, 'America/Chicago', now()),
  ('Dubuque County Jail', 'dubuque-county-jail', 'weird-history', 42.5, -90.6677, 'Dubuque', 'IA', 'The Egyptian Revival former county jail is one of Dubuque''s most unusual nineteenth-century civic buildings, with heavy stone walls and fortress-like details. Interior access is not reliably public, so OddWay should treat it as an exterior architectural stop unless an authorized event is offered.', 'roadside', 'https://www.cityofdubuque.org/', null, 'America/Chicago', now()),
  ('Old Fort Madison', 'old-fort-madison', 'weird-history', 40.6294, -91.2947, 'Fort Madison', 'IA', 'A reconstructed early U.S. military fort interprets the tense frontier period surrounding the War of 1812 on the upper Mississippi. Stockades, blockhouses and living-history programs make the site feel physically separated from the modern riverfront around it.', 'limited', 'https://www.fortmadison-ia.com/', null, 'America/Chicago', now()),
  ('Chief Wapello Memorial Park', 'chief-wapello-memorial-park', 'weird-history', 40.9957, -92.3068, 'Agency', 'IA', 'A memorial and cemetery complex honors Meskwaki leader Wapello and preserves the graves of early regional figures. The site should be approached as a respectful historic landscape rather than a novelty stop.', 'open', 'https://history.iowa.gov/', null, 'America/Chicago', now()),
  ('Meskwaki Cultural Center & Museum', 'meskwaki-cultural-center-museum', 'weird-history', 41.9968, -92.6582, 'Tama', 'IA', 'Operated by the Meskwaki Nation, this museum interprets tribal history, material culture and continuing community life in Iowa. It gives travelers a primary-source cultural stop rather than relying on outsider retellings.', 'limited', 'https://www.meskwaki.org/', null, 'America/Chicago', now()),
  ('Fort Atkinson State Preserve', 'fort-atkinson-state-preserve', 'weird-history', 43.1442, -91.9349, 'Fort Atkinson', 'IA', 'Stone and earthwork remains survive from a U.S. Army post built in the 1840s to monitor the Ho-Chunk during their forced relocation period. The preserved barracks and walls create one of Iowa''s most substantial frontier military ruins.', 'open', 'https://www.iowadnr.gov/places-go/state-preserves', null, 'America/Chicago', now()),
  ('Iowa Great Lakes Maritime Museum', 'iowa-great-lakes-maritime-museum', 'museums', 43.3659, -95.13, 'Arnolds Park', 'IA', 'Historic boats, resort artifacts and lake transportation displays preserve the unusual tourism history of the Iowa Great Lakes. The museum sits beside Arnolds Park amusement park, making the area a dense cluster of nostalgic roadside attractions.', 'limited', 'https://okobojimuseum.org/', null, 'America/Chicago', now()),
  ('Okoboji Spirit Lake Massacre Monument', 'okoboji-spirit-lake-massacre-monument', 'weird-history', 43.4218, -95.1017, 'Spirit Lake', 'IA', 'A monument and museum complex interprets the violent 1857 conflict commonly called the Spirit Lake Massacre. OddWay should present the stop with careful historical context rather than sensationalizing the deaths or Indigenous history.', 'open', 'https://iowaculture.gov/history/sites/abigail-gardner-sharp-home', null, 'America/Chicago', now()),
  ('Abbie Gardner Sharp Cabin', 'abbie-gardner-sharp-cabin', 'weird-history', 43.3696, -95.1282, 'Arnolds Park', 'IA', 'This small cabin survives from the 1857 Spirit Lake conflict and became associated with survivor Abbie Gardner Sharp''s later interpretation of the event. It is a sensitive historic site with scheduled museum access.', 'limited', 'https://history.iowa.gov/history/sites/abigail-gardner-sharp-home', null, 'America/Chicago', now()),
  ('Little Brown Church in the Vale', 'little-brown-church-in-the-vale', 'weird-history', 42.9519, -92.5369, 'Nashua', 'IA', 'The small church inspired the famous nineteenth-century hymn ''The Church in the Wildwood'' and became a destination for weddings and music pilgrims. Its modest rural appearance hides an outsized place in American hymn history.', 'open', 'https://www.littlebrownchurch.org/', null, 'America/Chicago', now()),
  ('Floyd County Museum — Charles City Tractor History', 'floyd-county-museum-charles-city-tractor-history', 'weird-history', 43.0668, -92.674, 'Charles City', 'IA', 'The museum preserves artifacts from Charles City''s major role in tractor manufacturing, including material tied to Hart-Parr and Oliver. Early farm machines give the collection a strong mechanical and industrial OddWay angle.', 'limited', 'https://floydcountymuseum.org/', null, 'America/Chicago', now()),
  ('Kinney Pioneer Museum', 'kinney-pioneer-museum', 'museums', 43.1686, -93.2768, 'Mason City', 'IA', 'A sprawling collection of pioneer buildings, farm machinery, household objects and local artifacts creates a deliberately old-fashioned museum village. The density of unrelated historical objects makes it an especially good curiosity stop.', 'limited', 'https://www.kinneypioneermuseum.org/', null, 'America/Chicago', now()),
  ('Carroll County Freedom Rock', 'carroll-county-freedom-rock', 'roadside-oddities', 41.909, -95.0658, 'Manning', 'IA', 'One of the statewide Freedom Rock murals turns a large boulder into a detailed memorial honoring military service and local veterans. It is best treated as part of the wider Iowa Freedom Rock phenomenon rather than a stand-alone world-record attraction.', 'open', 'https://www.thefreedomrock.com/', null, 'America/Chicago', now()),
  ('Iowa State Fair Butter Cow', 'iowa-state-fair-butter-cow', 'roadside-oddities', 41.5954, -93.5568, 'Des Moines', 'IA', 'Each Iowa State Fair features a life-size cow sculpted from hundreds of pounds of butter inside a refrigerated display case. The temporary sculpture is one of the state''s strangest and most enduring annual traditions.', 'limited', 'https://www.iowastatefair.org/', null, 'America/Chicago', now()),
  ('Iowa State Fair Giant Slide', 'iowa-state-fair-giant-slide', 'roadside-oddities', 41.5956, -93.5547, 'Des Moines', 'IA', 'The giant yellow fair slide has carried generations of visitors down its steep lanes on burlap sacks. It operates only during the Iowa State Fair but has become a visual icon of the grounds.', 'limited', 'https://www.iowastatefair.org/', null, 'America/Chicago', now()),
  ('World Food Prize Hall of Laureates', 'world-food-prize-hall-of-laureates', 'roadside-oddities', 41.5857, -93.6226, 'Des Moines', 'IA', 'The restored former Des Moines Public Library now functions as an ornate ceremonial hall devoted to global agriculture and food security. Murals, stained glass and restored Beaux-Arts spaces make the interior unexpectedly elaborate.', 'limited', 'https://www.worldfoodprize.org/', null, 'America/Chicago', now()),
  ('Des Moines Skywalk System', 'des-moines-skywalk-system', 'roadside-oddities', 41.586, -93.625, 'Des Moines', 'IA', 'Miles of enclosed pedestrian bridges connect downtown buildings above street level, creating a second indoor circulation network through the city. The system can feel like navigating an elevated maze through offices, hotels and parking structures.', 'open', 'https://www.dsm.city/', null, 'America/Chicago', now()),
  ('Davenport Skybridge', 'davenport-skybridge', 'roadside-oddities', 41.5206, -90.5778, 'Davenport', 'IA', 'A glass-enclosed pedestrian bridge projects toward the Mississippi River and offers elevated views of the waterfront. Its curved, futuristic shape makes it one of downtown Davenport''s most unusual pieces of public infrastructure.', 'open', 'https://www.davenportiowa.com/', null, 'America/Chicago', now()),
  ('Putnam Museum — Ancient Egypt & Giant Screen Collections', 'putnam-museum-ancient-egypt-giant-screen-collections', 'museums', 41.546, -90.6037, 'Davenport', 'IA', 'The Putnam combines natural history, archaeology and cultural artifacts, including Egyptian material, fossils and taxidermy. Its eclectic mix makes it a classic old-style regional curiosity museum.', 'open', 'https://www.putnam.org/', null, 'America/Chicago', now()),
  ('German American Heritage Center', 'german-american-heritage-center', 'weird-history', 41.5239, -90.5741, 'Davenport', 'IA', 'Housed in a former immigrant hotel, this museum interprets the experiences of German newcomers who passed through Davenport in the nineteenth century. The preserved building itself is part of the story.', 'open', 'https://gahc.org/', null, 'America/Chicago', now()),
  ('Credit Island — Black Hawk Treaty Landscape', 'credit-island-black-hawk-treaty-landscape', 'weird-history', 41.501, -90.634, 'Davenport', 'IA', 'This Mississippi River island is tied to the War of 1812 Battle of Credit Island and later treaty-era history. Trails and memorials occupy a landscape whose quiet park setting contrasts with its violent past.', 'open', 'https://www.davenportiowa.com/parks', null, 'America/Chicago', now()),
  ('Keokuk National Cemetery', 'keokuk-national-cemetery', 'weird-history', 40.4115, -91.3855, 'Keokuk', 'IA', 'Rows of military graves fill one of the country''s oldest national cemeteries west of the Mississippi. The site contains Civil War dead and later veterans and should be treated strictly as a respectful historical cemetery.', 'open', 'https://www.cem.va.gov/cems/nchp/keokuk.asp', null, 'America/Chicago', now()),
  ('Mormon Handcart Park', 'mormon-handcart-park', 'weird-history', 41.6373, -91.5981, 'Iowa City', 'IA', 'A memorial park marks the staging area where handcart companies organized before beginning the difficult overland journey toward Utah in the 1850s. Interpretive signs connect suburban Iowa City to one of America''s strangest migration experiments.', 'open', 'https://www.icgov.org/', null, 'America/Chicago', now()),
  ('Iowa River Power Building', 'iowa-river-power-building', 'weird-history', 41.6828, -91.5667, 'Coralville', 'IA', 'A historic hydroelectric powerhouse and dam complex on the Iowa River preserves the look of early twentieth-century utility infrastructure. Even where interior businesses change, the industrial shell remains a dramatic river landmark.', 'roadside', 'https://www.coralville.org/', null, 'America/Chicago', now()),
  ('Coralville Old Town Hall / 1876 Schoolhouse Cluster', 'coralville-old-town-hall-1876-schoolhouse-cluster', 'weird-history', 41.6762, -91.5804, 'Coralville', 'IA', 'Small preserved civic buildings stand amid modern Coralville, creating a compact cluster of nineteenth-century local history. The contrast between the tiny historic structures and surrounding development is the main OddWay appeal.', 'open', 'https://www.coralville.org/', null, 'America/Chicago', now()),
  ('Riverside History Center — Star Trek Displays', 'riverside-history-center-star-trek-displays', 'roadside-oddities', 41.4796, -91.5816, 'Riverside', 'IA', 'Riverside''s local museum leans into the town''s adopted Star Trek identity alongside ordinary community history. It provides context for the nearby Captain Kirk future-birthplace marker and annual Trek Fest.', 'limited', 'https://www.riversideiowa.gov/', null, 'America/Chicago', now()),
  ('Trek Fest Grounds / USS Riverside Displays', 'trek-fest-grounds-uss-riverside-displays', 'roadside-oddities', 41.4802, -91.581, 'Riverside', 'IA', 'Public Star Trek-themed signs, props and festival installations around Riverside turn several downtown blocks into a playful fictional-history landscape. The displays vary over time but reinforce the town''s Captain Kirk identity.', 'open', 'https://trekfest.org/', null, 'America/Chicago', now()),
  ('RAGBRAI Hall of Fame / Iowa Bicycle Culture Displays', 'ragbrai-hall-of-fame-iowa-bicycle-culture-displays', 'weird-history', 41.587, -93.625, 'Des Moines', 'IA', 'Iowa''s cross-state bicycle ride has developed its own folklore, costumes, traditions and roadside culture over decades. Displays and rotating exhibits connected with RAGBRAI provide a physical entry point into that unusual statewide event.', 'limited', 'https://ragbrai.com/', null, 'America/Chicago', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as iowa from public.stops where state = 'IA';
